package com.taxplatform.startup;

import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Clock;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

final class SelfServiceTests {
    private static int passed,generated;
    private SelfServiceTests(){ }
    @FunctionalInterface private interface Test{void run()throws Exception;}
    private static void check(String name,Test test)throws Exception{test.run();passed++;System.out.println("PASS "+name);}
    private static void eq(Object a,Object b){if(!java.util.Objects.equals(a,b))throw new AssertionError("self-service assertion failed: "+a+" vs "+b);}
    private static void fail(int status,String code,Runnable work){try{work.run();}catch(Workspace.Problem e){eq(e.status,status);eq(e.code,code);return;}throw new AssertionError("rejection missing: "+code);}
    static Map<String,Object> body(Object... pairs){Map<String,Object> out=new LinkedHashMap<>();for(int i=0;i<pairs.length;i+=2)out.put((String)pairs[i],pairs[i+1]);return out;}
    static String csv(String number,String date,String amount,String igst,String itc){return GstReconciliation.HEADER+"\nSUPPLIER_A,INVOICE,"+number+","+date+","+amount+","+igst+",0.00,0.00,0.00,NO,"+itc;}
    static String books(){return csv("INV/01","2025-07-03","1000.00","180.00","NOT_APPLICABLE");}
    static String statement(){return csv("INV/01","2025-07-03","1000.00","180.00","AVAILABLE");}
    static Map<String,Object> importBody(Workspace w,String owner,String id,String books,String statement){return body("operation","IMPORT","request_id",Workspace.id(),"expected_revision",w.readCase(owner,id).get("revision"),"period","2025-07","books_csv",books,"statement_csv",statement,"same_entity_confirmed",true,"books_complete",true,"statement_complete",true);}
    static Map<String,Object> reviewBody(Workspace w,String owner,String id,String action){var sheet=w.gst(owner,id);var group=Json.map(Json.list(sheet.get("groups")).get(0));return body("operation","REVIEW","request_id",Workspace.id(),"expected_revision",w.readCase(owner,id).get("revision"),"worksheet_version",sheet.get("version"),"group_id",group.get("id"),"action",action,"observations_reviewed",true);}
    static Map<String,Object> scopeBody(Workspace w,String owner,String id){Map<String,Object> answers=new LinkedHashMap<>();for(String key:SelfServicePreparation.QUESTIONS.keySet())answers.put(key,List.of("individual","ordinary_resident","adult_under_60_throughout_fy","salary_and_ordinary_interest_only").contains(key)?"YES":"NO");return body("request_id",Workspace.id(),"expected_revision",w.readCase(owner,id).get("revision"),"period","FY2025-26-AY2026-27","answers",answers,"answers_reviewed",true);}
    private static String create(Workspace w,String owner){return (String)w.createCase(owner,body("title","Preparation sample","request_id",Workspace.id())).get("id");}
    private static String account(Workspace w,String name,String role){String password="Synthetic-"+Workspace.id();return (String)(role.equals("CUSTOMER")?w.register(body("username",name,"display_name",name,"password",password)):w.createOperator(name,name,password,role)).get("id");}
    private static List<String> issues(String left,String right){return Json.list(GstReconciliation.groups(left,right,"v1").get(0).get("issues")).stream().map(String.class::cast).toList();}
    public static void main(String[] args)throws Exception{
        check("exact match compares all tax components without granting eligibility",()->{var g=GstReconciliation.groups(books(),statement(),"v1").get(0);eq(g.get("status"),"MATCHED_OBSERVATIONS");eq(g.get("credit_eligibility"),"NOT_DETERMINED");});
        check("unknown is not zero or a usable match",()->eq(issues(books(),statement().replace("1000.00","UNKNOWN")).contains("INCOMPLETE_DATA"),true));
        check("amount precision no exponent sign whitespace or silent rounding",()->{for(String v:List.of("","1e3","1.001","-1"," 1","01","NaN","1000000000"))fail(400,"GST_EXPLICIT_AMOUNT_REQUIRED",()->GstReconciliation.parse(csv("A","2025-07-01",v,"0","NOT_APPLICABLE"),false));});
        check("invalid leap dates are rejected and valid leap dates survive",()->{fail(400,"GST_DOCUMENT_DATE",()->GstReconciliation.parse(csv("A","2025-02-29","1","0","NOT_APPLICABLE"),false));eq(GstReconciliation.parse(csv("A","2024-02-29","1","0","NOT_APPLICABLE"),false).size(),1);});
        check("invoice identity keeps case slash hyphen and supplier distinctions",()->{for(String v:List.of("inv/01","INV-01","INV01"))eq(GstReconciliation.groups(books(),statement().replace("INV/01",v),"v1").size(),2);eq(GstReconciliation.groups(books(),statement().replace("SUPPLIER_A","SUPPLIER_B"),"v1").size(),2);});
        check("same number across fiscal years is not silently matched",()->eq(GstReconciliation.groups(books(),statement().replace("2025-07-03","2026-07-03"),"v1").size(),2));
        check("same year different date remains visible as a mismatch",()->eq(issues(books(),statement().replace("2025-07-03","2025-08-03")).contains("DIFFERENT_DOCUMENT_DATE"),true));
        check("identical duplicate rows are not silently deduplicated",()->{String duplicate=books()+"\n"+books().split("\n")[1];var g=GstReconciliation.groups(duplicate,statement(),"v1").get(0);eq(Json.list(g.get("books")).size(),2);eq(Json.list(g.get("issues")).contains("DUPLICATE_DOCUMENT_KEY"),true);});
        check("RCM unavailable credit unknown and mixed components require review",()->{eq(issues(books().replace(",NO,",",YES,"),statement().replace(",NO,",",YES,")).contains("REVERSE_CHARGE_REVIEW"),true);for(String label:List.of("UNKNOWN","NOT_AVAILABLE"))eq(issues(books(),statement().replace("AVAILABLE",label)).contains("STATEMENT_ITC_"+label),true);eq(issues(books().replace("180.00,0.00","180.00,90.00"),statement().replace("180.00,0.00","180.00,90.00")).contains("MIXED_TAX_COMPONENTS_REVIEW"),true);});
        check("amendments do not claim an unimplemented linkage policy",()->eq(issues(books().replace(",INVOICE,",",AMENDMENT,"),statement().replace(",INVOICE,",",AMENDMENT,")).contains("AMENDMENT_LINKAGE_UNSUPPORTED"),true));
        check("books cannot supply a statement availability authority",()->fail(400,"GST_ITC_SOURCE_LABEL",()->GstReconciliation.parse(statement(),false)));
        check("normalized input rejects real-ID format formula quotes columns and excess rows",()->{fail(400,"GST_SUPPLIER_ALIAS_REQUIRED",()->GstReconciliation.parse(books().replace("SUPPLIER_A","27ABCDE1234F1Z5"),false));fail(400,"GST_DOCUMENT_NUMBER",()->GstReconciliation.parse(books().replace("INV/01","=SUM(A1)"),false));fail(400,"GST_NORMALIZED_CSV_REQUIRED",()->GstReconciliation.parse(books().replace("INV/01","\"INV/01\""),false));fail(400,"GST_COLUMN_COUNT",()->GstReconciliation.parse(books()+",extra",false));fail(400,"GST_USE_0_TO_100_ROWS",()->GstReconciliation.parse(GstReconciliation.HEADER+"\n"+("A,INVOICE,X,2025-07-01,0,0,0,0,0,NO,NOT_APPLICABLE\n").repeat(101),false));});
        check("explicit empty files preserve missing-side evidence without declaring a nil return",()->{eq(issues(books(),GstReconciliation.HEADER).contains("MISSING_IN_STATEMENT"),true);eq(issues(GstReconciliation.HEADER,statement()).contains("MISSING_IN_BOOKS"),true);eq(GstReconciliation.groups(GstReconciliation.HEADER,GstReconciliation.HEADER,"empty").size(),0);});
        check("each changed tax component is independently detected",()->{for(String component:List.of("taxable","igst","cgst","sgst","cess")){int index=List.of("taxable","igst","cgst","sgst","cess").indexOf(component)+4;for(int i=1;i<=12;i++){String[] cells=statement().split("\n")[1].split(",");cells[index]=Integer.toString(i);String s=GstReconciliation.HEADER+"\n"+String.join(",",cells);eq(issues(books(),s).contains("DIFFERENT_"+component.toUpperCase(java.util.Locale.ROOT)),true);generated++;}}});
        Path directory=Files.createTempDirectory("self-service-unit-");
        try(VaultStore store=new VaultStore(directory.resolve("data"),directory.resolve("key"))){Workspace w=new Workspace(store,Clock.systemUTC());String owner=account(w,"self_owner","CUSTOMER"),other=account(w,"self_other","CUSTOMER"),admin=account(w,"self_admin","ADMIN"),preparer=account(w,"self_preparer","PREPARER");
            check("new ITR declarations retain unknowns and external release gates",()->{String id=create(w,owner);var result=w.itrReadiness(owner,id);eq(result.get("scope_review_current"),false);eq(Json.list(result.get("unknown_answers")).size(),14);eq(result.get("filing_available"),false);eq(result.get("scope_is_statutory_form_eligibility"),false);});
            check("scope blockers and unknown answers cannot become routine completion",()->{String id=create(w,owner);var p=scopeBody(w,owner,id);Json.map(p.get("answers"));Map<String,Object> answers=Json.map(p.get("answers"));answers.put("capital_gains","YES");p.put("answers",answers);w.saveItrScope(owner,id,p);eq(w.itrReadiness(owner,id).get("status"),"EXPANDED_WORKFLOW_REQUIRED");eq(w.itrReadiness(owner,id).get("ca_required_determined"),false);});
            check("scope requires exact questions explicit review and fixed period",()->{String id=create(w,owner);var p=scopeBody(w,owner,id);p.put("answers_reviewed",false);fail(400,"ITR_EXPLICIT_SCOPE_REVIEW_REQUIRED",()->w.saveItrScope(owner,id,p));p.put("answers_reviewed",true);p.put("period","FY2026-27-AY2027-28");fail(400,"ITR_PREPARATION_PERIOD_UNSUPPORTED",()->w.saveItrScope(owner,id,p));p.put("period","FY2025-26-AY2026-27");p.put("answers",Map.of("individual","YES"));fail(400,"ITR_SCOPE_ANSWERS_REQUIRED",()->w.saveItrScope(owner,id,p));});
            check("material changes make saved ITR scope review stale",()->{String id=create(w,owner);var p=scopeBody(w,owner,id);w.saveItrScope(owner,id,p);eq(w.itrReadiness(owner,id).get("scope_review_current"),true);var row=w.readCase(owner,id);w.edit(owner,id,body("operation","PROPOSE","request_id",Workspace.id(),"expected_revision",row.get("revision"),"field","SALARY","text","1 lakh","unit",""));eq(w.itrReadiness(owner,id).get("scope_review_current"),false);eq(w.saveItrScope(owner,id,p).get("status"),"REPLAYED");eq(w.itrReadiness(owner,id).get("scope_review_current"),false);});
            check("private tools remain owner-only for customer admin and granted preparer",()->{String id=create(w,owner);w.gstCommand(owner,id,importBody(w,owner,id,books(),statement()));var row=w.readCase(owner,id);w.grant(owner,id,body("request_id",Workspace.id(),"expected_revision",row.get("revision"),"preparer_username","self_preparer","expires_days",7L,"consent",true));for(String actor:List.of(other,admin,preparer)){fail(404,"CASE_NOT_FOUND",()->w.itrReadiness(actor,id));fail(404,"CASE_NOT_FOUND",()->w.gst(actor,id));fail(404,"CASE_NOT_FOUND",()->w.gstExport(actor,id));fail(404,"CASE_NOT_FOUND",()->w.gstCommand(actor,id,importBody(w,owner,id,books(),statement())));}eq(w.readCase(preparer,id).containsKey("self_service"),false);});
            check("an observation match needs explicit review and never claims credit",()->{String id=create(w,owner);w.gstCommand(owner,id,importBody(w,owner,id,books(),statement()));eq(w.gst(owner,id).get("status"),"PREPARATION_INCOMPLETE");w.gstCommand(owner,id,reviewBody(w,owner,id,"REVIEWED_MATCH"));var sheet=w.gst(owner,id);eq(sheet.get("status"),"OBSERVATION_REVIEW_COMPLETE");eq(sheet.get("credit_eligibility"),"NOT_DETERMINED");eq(sheet.get("itc_claim_amount"),null);eq(sheet.get("filing_available"),false);});
            check("mismatch cannot be overridden to match by any action",()->{String id=create(w,owner);w.gstCommand(owner,id,importBody(w,owner,id,books(),statement().replace("180.00","170.00")));fail(409,"GST_ACTION_NOT_ALLOWED_FOR_GROUP",()->w.gstCommand(owner,id,reviewBody(w,owner,id,"REVIEWED_MATCH")));w.gstCommand(owner,id,reviewBody(w,owner,id,"NO_CLAIM_REVIEW"));eq(w.gst(owner,id).get("open_issue_groups"),1);eq(w.gst(owner,id).get("status"),"PREPARATION_INCOMPLETE");});
            check("missing coverage cannot be upgraded by matched rows",()->{String id=create(w,owner);var p=importBody(w,owner,id,books(),statement());p.put("books_complete",false);w.gstCommand(owner,id,p);w.gstCommand(owner,id,reviewBody(w,owner,id,"REVIEWED_MATCH"));eq(w.gst(owner,id).get("status"),"PREPARATION_INCOMPLETE");});
            check("reimport invalidates review version and exact retry cannot overwrite later sheet",()->{String id=create(w,owner);var p=importBody(w,owner,id,books(),statement());w.gstCommand(owner,id,p);var review=reviewBody(w,owner,id,"REVIEWED_MATCH");w.gstCommand(owner,id,review);w.gstCommand(owner,id,importBody(w,owner,id,books(),statement()));eq(w.gst(owner,id).get("reviewed_groups"),0);String version=(String)w.gst(owner,id).get("version");eq(w.gstCommand(owner,id,p).get("status"),"REPLAYED");eq(w.gst(owner,id).get("version"),version);review.put("request_id",Workspace.id());review.put("expected_revision",w.readCase(owner,id).get("revision"));review.put("group_id",Json.map(Json.list(w.gst(owner,id).get("groups")).get(0)).get("id"));fail(409,"STALE_GST_WORKSHEET",()->w.gstCommand(owner,id,review));});
            check("authority and altered command replay are rejected",()->{String id=create(w,owner);var p=importBody(w,owner,id,books(),statement());w.gstCommand(owner,id,p);p.put("statement_complete",false);fail(409,"IDEMPOTENCY_CONFLICT",()->w.gstCommand(owner,id,p));p.put("credit_eligible",true);fail(400,"UNEXPECTED_FIELDS",()->w.gstCommand(owner,id,p));});
            check("clear removes latest source content and retained old receipt cannot resurrect it",()->{String id=create(w,owner);var p=importBody(w,owner,id,books(),statement());w.gstCommand(owner,id,p);w.gstCommand(owner,id,body("operation","CLEAR","request_id",Workspace.id(),"expected_revision",w.readCase(owner,id).get("revision")));eq(w.gstCommand(owner,id,p).get("status"),"REPLAYED");eq(w.gst(owner,id).get("status"),"NO_GST_WORKSHEET");eq(Json.encode(w.exportCase(owner,id)).contains("INV/01"),false);});
            check("source aliases amounts and review payloads stay out of operational audit",()->{String audit=Json.encode(w.audit(admin));for(String secret:List.of("INV/01","SUPPLIER_A","1000.00","180.00","books_csv","statement_itc"))eq(audit.contains(secret),false);});
            check("GST export is preparation JSON and not the provider return format",()->{String id=create(w,owner);w.gstCommand(owner,id,importBody(w,owner,id,books(),statement()));var result=w.gstExport(owner,id);eq(result.get("format"),"GST_PREPARATION_REVIEW_NOT_A_RETURN");eq(result.get("itc_eligibility_determined"),false);eq(w.readCase(owner,id).containsKey("self_service"),false);eq(Json.map(w.exportCase(owner,id).get("case")).containsKey("self_service_preparation"),true);});
        }finally{try(var paths=Files.walk(directory)){for(Path path:paths.sorted(java.util.Comparator.reverseOrder()).toList())Files.deleteIfExists(path);}}
        System.out.println(Json.encode(Map.of("self_service_named_groups",passed,"generated_component_mismatches",generated,"independent_tax_approval",false,"native_gst_parser",false,"filing_available",false)));
    }
}
